example:
Eingabe: "Bewehrungspläne Bodenplatte vom Tragwerksplaner immer noch nicht da, sollten heute kommen. Von 6 Leuten 2 umgesetzt, 4 stehen rum." Ausgabe: { "intent": "letter", "letter_type": "behinderung", "outcome": "anzeige", "facts": { "ursache": "Bewehrungspläne Bodenplatte vom Tragwerksplaner fehlen", "datum_beginn": "heute", "betroffene_leistung": "Bodenplatte bewehren", "arbeitskraefte_geplant": 6, "arbeitskraefte_umgesetzt": 2, "arbeitskraefte_ohne_produktive_arbeit": 4 }, "reason": "Fehlende Pläne des Auftraggebers verhindern den Beginn der Bewehrung – das ist eine Behinderung." }
Eingabe: "Unser Turmdrehkran hat seit heute früh einen Hydraulikschaden, Monteur kommt morgen." Ausgabe: { "intent": "letter", "letter_type": "behinderung", "outcome": "eigener_bereich", "facts": { "ursache": "Hydraulikschaden am eigenen Turmdrehkran", "datum_beginn": "seit heute früh", "massnahmen": "Monteur kommt morgen" }, "reason": "Der Kran gehört Ihnen – ein Geräteausfall im eigenen Bereich ist in der Regel keine Behinderung durch den Auftraggeber." }
Eingabe: "Pumpe war heute Vormittag 1 Stunde aus, Betonage trotzdem planmäßig fertig." Ausgabe: { "intent": "letter", "letter_type": "behinderung", "outcome": "keine_anzeige", "facts": { "ursache": "Pumpe 1 Stunde ausgefallen", "datum_beginn": "heute Vormittag", "auswirkung": "keine, Betonage planmäßig fertig" }, "reason": "Die Störung hatte keine Auswirkung auf Termine oder Kosten." }
